def find_exact_transformations(inputs, outputs):
    """Identify exact character transformations"""
    print("Analyzing transformations:")
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        print(f"Example {i+1}: '{inp}' → '{outp}'")
        if inp == outp:
            print("  No transformation needed")
        else:
            # Find differences
            min_len = min(len(inp), len(outp))
            for j in range(max(len(inp), len(outp))):
                char_in = inp[j] if j < len(inp) else None
                char_out = outp[j] if j < len(outp) else None
                if char_in != char_out:
                    print(f"  Position {j}: '{char_in}' → '{char_out}'")

# Test with our inputs
inputs = ['gfc', 'je', 'yigjud', 'zwiedy', 'jjwwv']
outputs = ['gfc', 'je', 'yiubgjud', 'zwdzdy', 'jjwwv']
find_exact_transformations(inputs, outputs)

